let remote = [], catalogBusy = false, catalogStatus = 'Loading release catalog…';
let showSamples = new URLSearchParams(location.search).get('demo') === '1';
const allProjects = () => [...remote, ...own, ...(showSamples ? seeds.filter(p=>!remote.some(r=>r.id===p.id)) : [])];
function renderCatalogStatus() {
  $('#catalog-status').textContent = catalogStatus;
  $('#refresh-catalog').disabled = catalogBusy;
}
async function refreshCatalog() {
  if (catalogBusy) return;
  catalogBusy = true;
  catalogStatus = 'Checking for new releases…';
  renderCatalogStatus();
  try {
    const response = await fetch(new URL('catalog.json', import.meta.url), {cache: 'no-store', signal: AbortSignal.timeout(12000)});
    if (!response.ok) throw new Error('Catalog unavailable.');
    const catalog = validateCatalog(await response.json());
    remote = displayProjects(catalog);
    try { localStorage.setItem('workshop-catalog-v1', JSON.stringify(catalog)); } catch {}
    catalogStatus = `${remote.length} published ${remote.length === 1 ? 'project' : 'projects'} · checked ${new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}`;
  } catch {
    if (!remote.length) {
      try { remote = displayProjects(JSON.parse(localStorage.getItem('workshop-catalog-v1'))); } catch {}
    }
    catalogStatus = remote.length ? 'Connection unavailable · showing the last saved catalog. Downloads need internet.' : 'Cannot load the catalog. Check your connection and press Refresh.';
  } finally {
    catalogBusy = false;
    renderCatalogStatus();
    const hash = location.hash.slice(1) || 'browse';
    if (hash === 'browse' || hash.startsWith('project/')) route();
  }
}
function onlineContent(p) {
  if (activeTab === 'versions') return `<div class="description"><h2>Releases</h2><p>Download a version matching your Minecraft version and loader.</p><div class="table-wrap"><table><thead><tr><th>Version</th><th>Minecraft / loader</th><th>Release</th></tr></thead><tbody>${p.releases.map((r,i)=>`<tr><td>${esc(r.version)}<br><small>${esc(r.filename)}</small></td><td>${esc(r.mc)} · ${esc(r.loader)}</td><td><button class="button" data-action="online-download" data-id="${esc(p.id)}" data-release="${i}">Download</button></td></tr><tr><td colspan="3"><small>SHA-256</small><code class="checksum">${esc(r.sha256)}</code><p>${esc(r.changelog)}</p></td></tr>`).join('')}</tbody></table></div></div>`;
  return projectContent(p);
}
function onlineView(p) {
  return `<div class="breadcrumb"><a href="#browse">Discover</a> / ${esc(p.type)}</div><header class="project-header">${icon(p)}<div><h1>${esc(p.title)}</h1><p>by ${esc(p.author)} · ${esc(p.type)}</p><div class="tags"><span class="tag ai">${esc(p.method)}</span><span class="tag">${esc(p.loader)}</span><span class="tag local">Published release</span></div></div></header><div class="project-layout"><section><div class="tabs" role="tablist" aria-label="Project information">${['overview','versions','compatibility'].map(t=>`<button class="tab ${activeTab===t?'active':''}" role="tab" id="tab-${t}" aria-selected="${activeTab===t}" aria-controls="project-content" data-tab="${t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div id="project-content" role="tabpanel" aria-labelledby="tab-${activeTab}">${onlineContent(p)}</div></section><aside><div class="side-card"><h2>Latest published release</h2><dl><dt>Version</dt><dd>${esc(p.version)}</dd><dt>Minecraft / loader</dt><dd>${esc(p.mc)} · ${esc(p.loader)}</dd><dt>File</dt><dd>${esc(p.filename)}</dd><dt>Size</dt><dd>${(p.size/1048576).toFixed(2)} MB</dd></dl><button class="button primary" style="margin-top:22px" data-action="online-download" data-id="${esc(p.id)}" data-release="0">Download release</button><p class="muted" style="font-size:.78rem;margin-top:12px">Hosted on GitHub Releases. Compatibility is creator-declared; the Workshop does not scan or execute files.</p><small>SHA-256</small><code class="checksum">${esc(p.sha256)}</code></div><div class="side-card"><h2>Project information</h2><dl><dt>License</dt><dd>${esc(p.license)}</dd><dt>AI tools</dt><dd>${esc(p.tools || 'None disclosed')}</dd><dt>Source</dt><dd>${p.source?`<a class="text-button" href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">View source</a>`:'Not linked'}</dd></dl><a class="button ghost" style="margin-top:20px" href="https://github.com/${REPOSITORY}/releases" target="_blank" rel="noopener noreferrer">GitHub releases</a></div></aside></div>`;
}
function publishing() {
  return `<article class="local-about"><div class="eyebrow">CREATOR TOOLS</div><h1>Publish once.<br>Find it in the Workshop.</h1><p>Finished release files go to MubbleYT/mubbles-workshop on GitHub. The publishing tool updates this catalog automatically after uploading the release.</p><div class="side-card"><h2>For Mubble’s releases</h2><p>Use PUBLISH-RELEASE.cmd from the downloaded source package, or connect the included publisher to your build process. Publishing requires your GitHub login. Downloading never needs an upload key.</p><a class="button primary" href="https://github.com/${REPOSITORY}" target="_blank" rel="noopener noreferrer">Open the repository</a></div><div class="side-card"><h2>Prepare a listing locally</h2><p>Try the project form and save a release file in this browser. Export its release details for the publisher when ready.</p><a class="button" href="#upload">Prepare a release</a></div><p class="muted">Public uploads from other creators are not enabled. Local drafts stay on this device until you publish them.</p></article>`;
}
let own=[], db=null, dbError='', activeTab='overview', pendingDelete=null, selectedFile=null;
let filter={q:'',types:new Set(),methods:new Set(),mc:'Any version',loader:'Any loader',sort:'featured'};
const openDB = new Promise((resolve,reject)=>{try{const r=indexedDB.open('mubbles-workshop-preview',1);r.onupgradeneeded=()=>r.result.createObjectStore('projects',{keyPath:'id'});r.onsuccess=()=>{db=r.result;db.onversionchange=()=>db.close();resolve(db)};r.onerror=()=>reject(r.error);r.onblocked=()=>reject(new Error('Close other Workshop tabs and refresh.'));}catch(e){reject(e)}});
async function getAll(){await openDB;return new Promise((resolve,reject)=>{const t=db.transaction('projects','readonly');const r=t.objectStore('projects').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function saveProject(p){await openDB;return new Promise((resolve,reject)=>{const t=db.transaction('projects','readwrite');t.objectStore('projects').put(p);t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||new Error('Storage cancelled.'))})}
async function removeProject(id){await openDB;return new Promise((resolve,reject)=>{const t=db.transaction('projects','readwrite');t.objectStore('projects').delete(id);t.oncomplete=resolve;t.onerror=()=>reject(t.error)})}
let toastTimer;
function toast(msg){$('#toast').textContent=msg;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4200)}
function card(p){return `<article class="card"><div class="card-head">${icon(p)}<div><h3><a href="#project/${esc(p.id)}">${esc(p.title)}</a></h3><span class="byline">by ${esc(p.author)} · ${esc(p.type)}</span></div></div><p>${esc(p.summary)}</p><div class="tags"><span class="tag ai">${esc(p.method)}</span><span class="tag">${esc(p.loader)}</span>${p.sample?'':`<span class="tag local">${p.online?'Published release':'Local project'}</span>`}</div><div class="card-bottom"><span>Minecraft ${esc(p.mc)}</span><span>${p.sample?'Sample listing':p.online?esc(p.version):esc(p.filename?'Release file attached':'No release file')}</span></div></article>`}
function match(p){const q=filter.q.trim().toLowerCase();const releaseMatches=(p.releases||[p]).some(r=>(filter.mc==='Any version'||r.mc===filter.mc)&&(filter.loader==='Any loader'||r.loader===filter.loader));return (!q||`${p.title} ${p.summary} ${p.tags.join(' ')} ${p.loader} ${p.tools}`.toLowerCase().includes(q))&&(!filter.types.size||filter.types.has(p.type))&&(!filter.methods.size||filter.methods.has(p.method))&&releaseMatches}
function sorted(list){return [...list].sort((a,b)=>filter.sort==='name'?a.title.localeCompare(b.title):filter.sort==='oldest'?a.created-b.created:b.created-a.created)}
function updateResults(){const list=sorted(allProjects().filter(match));$('#result-count').textContent=`${list.length} ${list.length===1?'project':'projects'}`;$('#results').innerHTML=list.length?list.map(card).join(''):'<div class="empty"><h2>No matching projects</h2><p>Try another search or clear your filters.</p><button class="button" data-action="clear">Clear filters</button></div>';$('#featured').hidden=!showSamples||remote.some(p=>p.id==='cinematic-shaders')||!!(filter.q||filter.types.size||filter.methods.size||filter.mc!=='Any version'||filter.loader!=='Any loader');}
function option(v,current){return `<option ${v===current?'selected':''}>${esc(v)}</option>`}
function browse(){const all=allProjects();const versions=[...new Set(all.flatMap(p=>(p.releases||[p]).map(r=>r.mc)))];const loaders=[...new Set(all.flatMap(p=>(p.releases||[p]).map(r=>r.loader)))];return `<div class="page-heading"><div><div class="eyebrow">THE WORKSHOP</div><h1>Find your next<br>world upgrade.</h1><p>Mods, shaders, and resource packs. Every creative process welcome.</p></div><span class="count-pill">${all.length} projects to explore</span></div><div class="layout"><aside class="filter-panel" aria-label="Project filters"><div class="filter-top"><h2>Filters</h2><button class="text-button" data-action="clear">Clear all</button></div><div class="filter-group"><h3>Project type</h3>${['Mods','Shaders','Resource packs','Modpacks'].map(t=>`<label class="filter-option"><input type="checkbox" data-filter="types" value="${t}" ${filter.types.has(t)?'checked':''}><span>${t}</span><span>${all.filter(p=>p.type===t).length}</span></label>`).join('')}</div><div class="filter-group"><h3>Minecraft version</h3><select aria-label="Minecraft version" data-filter="mc">${['Any version',...versions].map(v=>option(v,filter.mc)).join('')}</select></div><div class="filter-group"><h3>Loader / renderer</h3><select aria-label="Loader or renderer" data-filter="loader">${['Any loader',...loaders].map(v=>option(v,filter.loader)).join('')}</select></div><div class="filter-group"><h3>Creation method</h3>${['Human-made','AI-assisted','Primarily AI-generated','Fully AI-generated'].map(t=>`<label class="filter-option"><input type="checkbox" data-filter="methods" value="${t}" ${filter.methods.has(t)?'checked':''}><span>${t}</span></label>`).join('')}</div><div class="filter-note">Judge the project.<br>Know how it was made.</div></aside><section>${!remote.length?'<div class="notice">No published releases loaded. Sample listings are available to preview the interface. <button class="text-button" data-action="samples">Show / hide samples</button></div>':''}<div class="search-row"><label class="searchbox"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/></svg><input id="search" type="text" aria-label="Search projects" placeholder="Search projects, tags, or tools…" value="${esc(filter.q)}"></label><select class="sort-select" id="sort" aria-label="Sort projects"><option value="featured" ${filter.sort==='featured'?'selected':''}>Recently added</option><option value="name" ${filter.sort==='name'?'selected':''}>Name A–Z</option><option value="oldest" ${filter.sort==='oldest'?'selected':''}>Oldest first</option></select></div><article class="featured" id="featured"><div class="eyebrow">IN THE SPOTLIGHT · SAMPLE PROJECT</div><h2>Your world. A different atmosphere.</h2><p>Mubble’s Cinematic Shaders brings together bold lighting, custom skies, and a little film-inspired magic.</p><div class="featured-bottom"><a class="button primary" href="#project/cinematic-shaders">Explore the project</a><span class="tag ai">Primarily AI-generated</span><span class="tag">Shaders</span></div><span class="featured-index" aria-hidden="true">01</span></article><div class="results-title"><h2>Explore projects</h2><span id="result-count" aria-live="polite"></span></div><div class="grid" id="results"></div></section></div>`;}
function projectView(p){return `<div class="breadcrumb"><a href="#browse">Discover</a> / ${esc(p.type)} / ${esc(p.title)}</div><header class="project-header">${icon(p)}<div><h1>${esc(p.title)}</h1><p>by ${esc(p.author)} · ${esc(p.type)}</p><div class="tags"><span class="tag ai">${esc(p.method)}</span><span class="tag">${esc(p.loader)}</span><span class="tag ${p.sample?'':'local'}">${p.sample?'Sample listing':'Local project'}</span></div></div></header><div class="project-layout"><section><div class="tabs" role="tablist" aria-label="Project information">${['overview','versions','compatibility'].map(t=>`<button class="tab ${activeTab===t?'active':''}" role="tab" id="tab-${t}" aria-selected="${activeTab===t}" aria-controls="project-content" data-tab="${t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div id="project-content" role="tabpanel" aria-labelledby="tab-${activeTab}">${projectContent(p)}</div></section><aside><div class="side-card"><h2>${p.sample?'Release preview':'Your release'}</h2><dl><dt>Project version</dt><dd>${esc(p.version)}</dd><dt>Minecraft</dt><dd>${esc(p.mc)}</dd><dt>Loader / renderer</dt><dd>${esc(p.loader)}</dd><dt>Release file</dt><dd>${p.filename?esc(p.filename):'No file attached'}</dd>${p.blob?`<dt>File size</dt><dd>${(p.blob.size/1048576).toFixed(2)} MB</dd>`:''}</dl><div style="margin-top:22px"><button class="button primary" data-action="download" data-id="${esc(p.id)}" ${p.blob?'':'disabled'}>Download ${p.blob?'release':'unavailable'}</button></div><p class="muted" style="font-size:.78rem;margin:12px 0 0">${p.sample?'Sample listings have no release files.':'File provided locally. No malware scan or compatibility test has been performed.'}</p></div><div class="side-card"><h2>Project information</h2><dl><dt>License</dt><dd>${esc(p.license)}</dd><dt>AI tools</dt><dd>${esc(p.tools||'None disclosed')}</dd><dt>Source code</dt><dd>${p.source?`<a class="text-button" href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">View source</a>`:'Not linked'}</dd></dl>${!p.sample?`<button class="button" style="margin-top:20px" data-action="export" data-id="${esc(p.id)}">Export release details</button><button class="button ghost" style="margin-top:10px" data-action="delete" data-id="${esc(p.id)}">Remove local project</button>`:''}</div></aside></div>`;}
function projectContent(p){if(activeTab==='versions')return `<div class="description"><h2>Versions</h2><p>${p.sample?'Illustrative metadata. No actual release is included.':'This release is saved only in this browser.'}</p><div class="table-wrap"><table><thead><tr><th>Version</th><th>Minecraft</th><th>Loader</th><th>Release</th></tr></thead><tbody><tr><td>${esc(p.version)}</td><td>${esc(p.mc)}</td><td>${esc(p.loader)}</td><td>${p.blob?`<button class="button" data-action="download" data-id="${esc(p.id)}">Download</button>`:'Sample only'}</td></tr></tbody></table></div>${p.changelog?`<h3 style="margin-top:24px">Changelog</h3><p>${esc(p.changelog)}</p>`:''}</div>`;if(activeTab==='compatibility')return `<div class="description"><h2>Compatibility</h2><div class="notice">${p.sample?'These are compatibility targets for the concept, not verified test results.':'Compatibility labels are creator declarations. The Workshop has not tested this release.'}</div><div class="table-wrap"><table><thead><tr><th>Component</th><th>Status</th></tr></thead><tbody>${[...new Set([p.loader,...p.compat])].map(c=>`<tr><td>${esc(c)}</td><td class="status">${p.sample?'Target · unverified':'Declared · unverified'}</td></tr>`).join('')}</tbody></table></div></div>`;return `<article class="description">${p.sample?'<div class="notice">Sample project page. The description represents a concept; no tested release is attached.</div>':''}<h2>About this project</h2><p>${esc(p.description)}</p>${p.features.length?`<h3>What’s inside</h3><ul>${p.features.map(f=>`<li>${esc(f)}</li>`).join('')}</ul>`:''}<div class="disclosure"><h3>Creation method: ${esc(p.method)}</h3><p>${p.method==='Human-made'?'Declared as human-made.':`AI tools disclosed: ${esc(p.tools||'Not specified')}. Human review and testing are separate from how a project was created.`}</p></div></article>`;}
function upload(){return `<div class="form-shell"><div class="breadcrumb"><a href="#browse">Discover</a> / Add a project</div><div class="form-heading"><div class="eyebrow">MAKE SOMETHING. SHARE HOW.</div><h1>Add your project.</h1><p>Prepare a draft and export its details for the release publisher.</p></div><div class="notice">Local draft: this saves to your browser. Export its details, then use the publishing tool to upload it. Files are never executed or scanned.</div>${dbError?`<div class="notice">Local storage is unavailable: ${esc(dbError)}. Try a normal browser window at localhost.</div>`:''}<form id="upload-form"><section class="form-section"><h2>01 / The project</h2><div class="form-grid"><div class="field wide"><label for="title">Project name *</label><input id="title" name="title" type="text" required maxlength="100" placeholder="Mubble’s …"></div><div class="field"><label for="type">Project type *</label><select id="type" name="type">${['Mods','Shaders','Resource packs','Modpacks'].map(x=>option(x,'Mods')).join('')}</select></div><div class="field"><label for="author">Creator *</label><input id="author" name="author" type="text" value="Mubble" required maxlength="60"></div><div class="field wide"><label for="summary">Short description *</label><input id="summary" name="summary" type="text" required maxlength="220" placeholder="What does your project bring to the world?"></div><div class="field wide"><label for="description">Description *</label><textarea id="description" name="description" required maxlength="10000" placeholder="Tell players what it does and how to use it."></textarea></div><div class="field"><label for="tags">Tags</label><input id="tags" name="tags" type="text" maxlength="200" placeholder="Lighting, atmosphere, survival"><small>Separate tags with commas.</small></div><div class="field"><label for="license">License *</label><select id="license" name="license">${['All rights reserved','MIT','Apache-2.0','GPL-3.0','CC BY 4.0','CC0 1.0'].map(x=>option(x,'All rights reserved')).join('')}</select></div></div></section><section class="form-section"><h2>02 / How it was made</h2><div class="form-grid"><div class="field"><label for="method">Creation method *</label><select id="method" name="method">${['Human-made','AI-assisted','Primarily AI-generated','Fully AI-generated'].map(x=>option(x,'AI-assisted')).join('')}</select></div><div class="field"><label for="tools">AI tools used</label><input id="tools" name="tools" type="text" maxlength="200" placeholder="ChatGPT, Claude, Grok…"></div><div class="field wide"><label for="source">Source code URL</label><input id="source" name="source" type="url" maxlength="2000" placeholder="https://github.com/you/your-project"><small>Required for primarily or fully AI-generated executable mods. HTTPS links only.</small></div></div></section><section class="form-section"><h2>03 / The release</h2><div class="form-grid"><div class="field"><label for="version">Project version *</label><input id="version" name="version" type="text" maxlength="40" value="1.0.0" required></div><div class="field"><label for="mc">Minecraft version *</label><input id="mc" name="mc" type="text" maxlength="40" value="26.3" required></div><div class="field"><label for="loader">Loader / renderer *</label><select id="loader" name="loader">${['Fabric','NeoForge','Forge','Quilt','Iris','Vanilla'].map(x=>option(x,'Fabric')).join('')}</select></div><div class="field"><label for="compat">Compatibility targets</label><input id="compat" name="compat" type="text" maxlength="300" placeholder="Sodium, Iris, Voxy…"><small>Creator declarations, not verified results.</small></div><div class="field wide"><label for="changelog">Changelog</label><textarea id="changelog" name="changelog" maxlength="5000" placeholder="What changed in this release?" style="min-height:85px"></textarea></div><div class="field wide"><label for="release">Release file *</label><div class="drop-zone" id="drop-zone"><strong id="file-label">Drop a release file here</strong><input id="release" name="release" type="file" accept=".jar,.zip,.mrpack" required><small>.jar for mods · .zip for packs · .mrpack for modpacks · Up to 100 MB</small></div></div></div></section><label class="check-label"><input type="checkbox" name="rights" required><span>I have permission to distribute this file and have described its creation method honestly.</span></label><p class="form-error" id="form-error" role="alert" hidden></p><div class="form-actions" style="margin-top:22px"><a class="button ghost" href="#browse">Cancel</a><button class="button primary" id="save-button" type="submit" ${dbError?'disabled':''}>Save local project</button></div></form></div>`;}
function library(){return `<div class="page-heading"><div><div class="eyebrow">YOUR CORNER OF THE WORKSHOP</div><h1>My projects.</h1><p>Listings and files you’ve added in this browser.</p></div><a class="button primary" href="#upload">＋ Add a project</a></div><div class="notice">Projects are stored on this device in this browser. Clearing browser data removes them. Keep your original release files.</div>${dbError?`<div class="notice">Storage unavailable: ${esc(dbError)}</div>`:''}<div class="grid">${own.length?sorted(own).map(card).join(''):'<div class="empty"><h2>Your workshop starts here.</h2><p>Add a mod, shader, or resource pack to try the project workflow.</p><a class="button primary" href="#upload">Add your first project</a></div>'}</div>`;}
function about(){return `<article class="local-about"><div class="eyebrow">OUR APPROACH</div><h1>Built for creators.<br>Open about the process.</h1><p>Human-made, AI-assisted, or AI-generated: players should be able to see what a project does, how it was created, and what it has actually been tested with.</p><div class="principle-grid"><div class="side-card"><h2>Creation is disclosed.</h2><p>AI involvement belongs in the project metadata. Discover projects by their creation method without hiding the process.</p></div><div class="side-card"><h2>Compatibility is specific.</h2><p>Minecraft versions, loaders, and renderer targets belong to each release. A declared target is different from a tested result.</p></div><div class="side-card"><h2>Permission comes first.</h2><p>Creators should own their work or have the rights to distribute it. Generated code does not remove licensing obligations.</p></div><div class="side-card"><h2>Releases stay available.</h2><p>Published files live on GitHub Releases. The catalog updates when a release is published. Local drafts stay in your browser; public creator accounts and moderation are future work.</p></div></div><div style="margin-top:28px"><a class="button primary" href="#browse">Explore the workshop</a></div></article>`;}

function supportMethod(label,key,detail){
  const value=SUPPORT[key];
  if(value){
    if(key==='paypal') return `<a class="button primary" href="${esc(value)}" target="_blank" rel="noopener noreferrer">Open ${esc(label)}</a>`;
    return `<div class="wallet-row"><code class="wallet-address">${esc(value)}</code><button class="button" data-action="copy-support" data-value="${esc(value)}">Copy address</button></div>`;
  }
  return `<button class="button ghost" disabled>${esc(label)} · setup pending</button><p class="muted support-note">${esc(detail)}</p>`;
}
function support(){
  return `<article class="local-about legal-page"><div class="eyebrow">KEEP THE WORKSHOP RUNNING</div><h1>Support Mubble’s Workshop.</h1><p>Every download stays free. Optional support helps cover domains, hosting, infrastructure, and continued development. Supporting does not unlock files, features, priority treatment, or other benefits.</p><div class="support-grid"><section class="side-card"><h2>PayPal</h2><p>For normal voluntary support in EUR or another supported currency.</p>${supportMethod('PayPal','paypal','A PayPal support link has not been configured yet.')}</section><section class="side-card"><h2>Bitcoin</h2><p>Send BTC directly to the Workshop wallet once the receiving address is configured.</p>${supportMethod('Bitcoin','bitcoin','A Bitcoin receiving address has not been configured yet.')}</section><section class="side-card"><h2>Ethereum</h2><p>Send ETH directly to the Workshop wallet once the receiving address is configured.</p>${supportMethod('Ethereum','ethereum','An Ethereum receiving address has not been configured yet.')}</section></div><div class="notice">Support is voluntary and is not a charitable donation. Do not send cryptocurrency until an address is shown on this page.</div><p class="muted legal-small">Mubble’s Workshop is an independent project and is not affiliated with Mojang or Microsoft.</p></article>`;
}
function tos(){
  return `<article class="local-about legal-page"><div class="eyebrow">TEMPORARY DRAFT</div><h1>Terms of Service.</h1><div class="notice">Development placeholder. These terms must be reviewed and finalized before a general public release.</div><h2>1. Free access and downloads</h2><p>Mubble’s Workshop currently provides project listings and free downloads. A download may be hosted by a third-party service such as GitHub Releases. Optional financial support is separate from access to files and does not unlock additional functionality.</p><h2>2. Project licenses</h2><p>Each project may have its own license. That project-specific license controls what you may do with the downloaded file, source code, assets, or other project content. Availability through the Workshop does not grant rights beyond the applicable license.</p><h2>3. Compatibility and safety</h2><p>Compatibility information may be creator-declared and unverified. Back up important worlds and files before installing mods, shaders, resource packs, or modpacks. Unless expressly stated otherwise, the Workshop does not guarantee that a release has been malware-scanned, tested with every listed configuration, or will work on your system.</p><h2>4. No warranty</h2><p>The service and its free downloads are provided on an as-is and as-available basis to the extent permitted by applicable law. Mandatory statutory rights remain unaffected.</p><h2>5. Acceptable use</h2><p>Do not misuse the service, interfere with its operation, attempt to gain unauthorized access, or use Workshop branding to falsely imply affiliation or endorsement.</p><h2>6. Changes and availability</h2><p>Projects, releases, links, and service features may change or be removed. These temporary terms may be replaced before public release.</p><h2>7. Minecraft notice</h2><p>NOT AN OFFICIAL MINECRAFT PRODUCT OR SERVICE. NOT APPROVED BY OR ASSOCIATED WITH MOJANG OR MICROSOFT.</p><p class="muted legal-small">Draft version: 0.1 · Development preview · 3 October 2026</p></article>`;
}
function impressum(){
  return `<article class="local-about legal-page"><div class="eyebrow">TEMPORARY PLACEHOLDER</div><h1>Impressum.</h1><div class="notice"><strong>Not ready for a public commercial launch.</strong> The legally required provider details must be inserted here before release. No personal address or identity information has been invented for this placeholder.</div><div class="side-card legal-fields"><h2>Provider information to complete</h2><dl><dt>Name / legal provider</dt><dd>[TO BE ADDED]</dd><dt>Service address</dt><dd>[TO BE ADDED]</dd><dt>Email address</dt><dd>[TO BE ADDED]</dd><dt>Additional registration / tax details</dt><dd>[ADD IF APPLICABLE]</dd><dt>Responsible for editorial content</dt><dd>[ADD IF APPLICABLE]</dd></dl></div><h2>Technical project</h2><p>Mubble’s Workshop is an independent Minecraft project hub. The source and release infrastructure is maintained through the MubbleYT/mubbles-workshop repository.</p><p>NOT AN OFFICIAL MINECRAFT PRODUCT OR SERVICE. NOT APPROVED BY OR ASSOCIATED WITH MOJANG OR MICROSOFT.</p><p class="muted legal-small">This page is intentionally incomplete while the project remains in development.</p></article>`;
}
function promptSupport(){
  const dialog=$('#support-dialog');
  if(!dialog||dialog.open)return;
  setTimeout(()=>{if(!dialog.open)dialog.showModal()},450);
}

function route(){const hash=location.hash.slice(1)||'browse';document.querySelectorAll('[data-nav]').forEach(n=>n.classList.toggle('active',n.dataset.nav===hash));const app=$('#app');if(hash==='browse'){app.innerHTML=browse();updateResults()}else if(hash==='upload'){selectedFile=null;app.innerHTML=upload();setupUpload()}else if(hash==='library'){app.innerHTML=library()}else if(hash==='about'){app.innerHTML=about()}else if(hash==='publish'){app.innerHTML=publishing()}else if(hash==='support'){app.innerHTML=support()}else if(hash==='tos'){app.innerHTML=tos()}else if(hash==='impressum'){app.innerHTML=impressum()}else if(hash.startsWith('project/')){const p=allProjects().find(p=>p.id===hash.slice(8));app.innerHTML=p?(p.online?onlineView(p):projectView(p)):'<div class="empty"><h1>Project not found.</h1><p>This project may have been removed, or the catalog may not be available.</p><a class="button" href="#browse">Back to discover</a></div>'}else{location.hash='browse';return}document.title=hash.startsWith('project/')?`${allProjects().find(p=>p.id===hash.slice(8))?.title||'Project'} · Mubble’s Workshop`:'Mubble’s Workshop';}
function clearFilters(){filter={q:'',types:new Set(),methods:new Set(),mc:'Any version',loader:'Any loader',sort:'featured'};route()}
document.addEventListener('input',e=>{if(e.target.id==='search'){filter.q=e.target.value;updateResults()}});
document.addEventListener('change',e=>{const k=e.target.dataset.filter;if(k){if(k==='types'||k==='methods'){e.target.checked?filter[k].add(e.target.value):filter[k].delete(e.target.value)}else{filter[k]=e.target.value}updateResults()}if(e.target.id==='sort'){filter.sort=e.target.value;updateResults()}});
document.addEventListener('click',async e=>{const tab=e.target.closest('[data-tab]');if(tab){activeTab=tab.dataset.tab;route();$(`#tab-${activeTab}`)?.focus();return}const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='refresh'){await refreshCatalog();return}if(b.dataset.action==='samples'){showSamples=!showSamples;route();return}if(b.dataset.action==='export'){const p=own.find(p=>p.id===b.dataset.id);if(p)exportMetadata(p);return}if(b.dataset.action==='online-download'){const p=remote.find(p=>p.id===b.dataset.id);const r=p?.releases[Number(b.dataset.release)];if(r){const a=document.createElement('a');a.href=r.downloadUrl;a.rel='noopener noreferrer';document.body.append(a);a.click();a.remove();toast('Opening the GitHub release download.');promptSupport()}return}if(b.dataset.action==='clear'){clearFilters()}if(b.dataset.action==='download'){const p=own.find(p=>p.id===b.dataset.id);if(p?.blob){const url=URL.createObjectURL(p.blob);const a=document.createElement('a');a.href=url;a.download=p.filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Your local release file is downloading.');promptSupport()}}if(b.dataset.action==='copy-support'){const value=b.dataset.value;if(value){try{await navigator.clipboard.writeText(value);toast('Support address copied.')}catch{toast('Could not copy automatically. Select the address manually.')}}}if(b.dataset.action==='delete'){pendingDelete=b.dataset.id;$('#confirm-dialog').showModal()}});
$('#close-support').onclick=()=>$('#support-dialog').close();
$('#open-support-page').onclick=()=>$('#support-dialog').close();
$('#cancel-delete').onclick=()=>$('#confirm-dialog').close();
$('#confirm-delete').onclick=async()=>{try{await removeProject(pendingDelete);own=own.filter(p=>p.id!==pendingDelete);$('#confirm-dialog').close();location.hash='library';toast('Local project removed.')}catch(e){toast('Could not remove this project. Try again.')}};
document.addEventListener('keydown',e=>{const tab=e.target.closest('[data-tab]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=['overview','versions','compatibility'];activeTab=e.key==='Home'?tabs[0]:e.key==='End'?tabs[2]:tabs[(tabs.indexOf(activeTab)+(e.key==='ArrowRight'?1:2))%3];route();$(`#tab-${activeTab}`).focus()}});
function setFile(file){selectedFile=file;$('#file-label').textContent=file?`${file.name} · ${(file.size/1048576).toFixed(2)} MB`:'Drop a release file here'}
function setupUpload(){const input=$('#release'),zone=$('#drop-zone');input.addEventListener('change',()=>setFile(input.files[0]));zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('drag')});zone.addEventListener('dragleave',()=>zone.classList.remove('drag'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('drag');if(e.dataTransfer.files.length){setFile(e.dataTransfer.files[0]);input.files=e.dataTransfer.files}});$('#type').addEventListener('change',e=>{input.accept=e.target.value==='Mods'?'.jar':e.target.value==='Modpacks'?'.mrpack':'.zip';$('#loader').value=e.target.value==='Shaders'?'Iris':e.target.value==='Resource packs'?'Vanilla':'Fabric'});$('#upload-form').addEventListener('submit',submitProject)}
async function submitProject(e){e.preventDefault();const form=e.target;const data=new FormData(form);const error=$('#form-error');const button=$('#save-button');error.hidden=true;button.disabled=true;button.textContent='Saving…';try{const val=k=>String(data.get(k)||'').trim();for(const k of ['title','author','summary','description','version','mc'])if(!val(k))throw new Error('Please complete all required text fields.');const file=selectedFile||$('#release').files[0];if(!file)throw new Error('Choose a release file first.');const ext=val('type')==='Mods'?'.jar':val('type')==='Modpacks'?'.mrpack':'.zip';if(!file.name.toLowerCase().endsWith(ext))throw new Error(`Choose a ${ext} file for this project type.`);if(file.size>100*1048576)throw new Error('Choose a file smaller than 100 MB.');if(file.size<4)throw new Error('The selected archive is empty or invalid.');const header=new Uint8Array(await file.slice(0,4).arrayBuffer());if(header[0]!==80||header[1]!==75||!((header[2]===3&&header[3]===4)||(header[2]===5&&header[3]===6)||(header[2]===7&&header[3]===8)))throw new Error('This file does not have a ZIP/JAR archive signature.');if(val('source')){const url=new URL(val('source'));if(url.protocol!=='https:'||url.username||url.password)throw new Error('Use a valid HTTPS source-code link.');}if(val('type')==='Mods'&&['Primarily AI-generated','Fully AI-generated'].includes(val('method'))&&!val('source'))throw new Error('Add a source-code URL for this AI-generated executable mod.');if(val('method')!=='Human-made'&&!val('tools'))throw new Error('List the AI tools used for this project.');const p={id:'local-'+crypto.randomUUID(),title:val('title'),author:val('author'),summary:val('summary'),description:val('description'),type:val('type'),icon:val('type')==='Shaders'?'shader':val('type')==='Resource packs'?'nature':'lights',method:val('method'),tools:val('tools'),source:val('source'),license:val('license'),version:val('version'),mc:val('mc'),loader:val('loader'),tags:val('tags').split(',').map(s=>s.trim()).filter(Boolean),compat:val('compat').split(',').map(s=>s.trim()).filter(Boolean),features:[],changelog:val('changelog'),filename:file.name,blob:file,created:Date.now(),sample:false};await saveProject(p);own.unshift(p);activeTab='overview';location.hash='project/'+p.id;toast('Project saved locally. Your release file is ready to download.')}catch(err){error.hidden=false;error.textContent=err.name==='QuotaExceededError'?'Your browser has no storage space for this file. Try a smaller release.':err.message||'Could not save this project. Your form is still here.';}finally{button.disabled=false;button.textContent='Save local project'}}
window.addEventListener('hashchange',()=>{activeTab='overview';route();window.scrollTo(0,0)});
(async()=>{try{own=await getAll()}catch(e){dbError=e.message||'Browser storage is blocked.'}route();await refreshCatalog()})();
// Expose the same catalog search and project navigation when WebMCP is supported.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};register({name:'search_workshop_projects',title:'Search Workshop projects',description:'Search the Workshop catalog and update the visible Discover results. Does not upload or publish anything.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.query!=='string'||input.query.length>200||Object.keys(input).some(k=>k!=='query'))throw new Error('Provide a query string up to 200 characters.');filter={q:input.query,types:new Set(),methods:new Set(),mc:'Any version',loader:'Any loader',sort:'featured'};location.hash='browse';route();return {projects:sorted(allProjects().filter(match)).map(p=>({id:p.id,title:p.title,type:p.type,sample:p.sample}))}}});register({name:'open_workshop_project',title:'Open Workshop project',description:'Open a known project page in the Workshop.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.id!=='string'||Object.keys(input).some(k=>k!=='id'))throw new Error('Provide a project id.');const p=allProjects().find(p=>p.id===input.id);if(!p)throw new Error('Project not found.');activeTab='overview';location.hash='project/'+p.id;route();return {id:p.id,title:p.title,sample:p.sample}}});}

function exportMetadata(p) {
  const id = p.title.replace(/^mubble['’]s\s*/i, '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'my-project';
  const fields = ['title','author','type','summary','description','method','tools','source','license','tags','features','icon','version','mc','loader','compat','changelog'];
  const metadata = {id, ...Object.fromEntries(fields.map(k=>[k,p[k]])), rightsConfirmed:true};
  const url = URL.createObjectURL(new Blob([JSON.stringify(metadata,null,2)+'\n'],{type:'application/json'}));
  const a=document.createElement('a');a.href=url;a.download=id+'-release.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);
  toast('Release details exported. Use them with the publishing tool and your original file.');
}
